// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict to valid inputs that would reach the transfer/send call
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        // Deploy a contract that cannot receive Ether (no receive/fallback)
        address noReceiveContract = address(new NoReceive());

        // Act as owner
        vm.prank(address(this));

        // Try the call and check if it reverts
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendTo(address,uint256)", noReceiveContract, amount));

        // The reference (using transfer) should always revert for a contract that rejects Ether
        // The buggy version (using send) would not revert
        assertTrue(success == false);
    }
}

contract NoReceive {
    // No receive or fallback function, so it cannot receive Ether
}

